// Throwaway diagnostic script — NOT part of the repo. Compares PLP/PDP/Cart pricing
// for one real sale item via live SCAPI calls. Never logs the client secret or access token.
const SHORT_CODE = process.env.COMMERCE_API_SHORT_CODE;
const ORG_ID = process.env.COMMERCE_API_ORGANIZATION_ID;
const CLIENT_ID = process.env.COMMERCE_API_CLIENT_ID;
const CLIENT_SECRET = process.env.PWA_KIT_SLAS_CLIENT_SECRET;
const SITE_ID = 'ZimmermannAU';
const BASE = `https://${SHORT_CODE}.api.commercecloud.salesforce.com`;

async function getToken() {
  const basicAuth = Buffer.from(`${CLIENT_ID}:${CLIENT_SECRET}`).toString('base64');
  const res = await fetch(`${BASE}/shopper/auth/v1/organizations/${ORG_ID}/oauth2/token`, {
    method: 'POST',
    headers: { Authorization: `Basic ${basicAuth}`, 'Content-Type': 'application/x-www-form-urlencoded' },
    body: new URLSearchParams({ grant_type: 'client_credentials', channel_id: SITE_ID }).toString(),
  });
  const text = await res.text();
  if (!res.ok) throw new Error(`token failed: ${res.status} ${text}`);
  const json = JSON.parse(text);
  // Print only the field NAMES present in the response, never values, so we can confirm the
  // customer-id claim's real key without leaking the token.
  console.log('TOKEN RESPONSE KEYS:', Object.keys(json));
  return json; // contains access_token + customer_id (usually)
}

async function search(token, q) {
  const url = `${BASE}/search/shopper-search/v1/organizations/${ORG_ID}/product-search?siteId=${SITE_ID}&q=${encodeURIComponent(q)}&limit=25`;
  const res = await fetch(url, { headers: { Authorization: `Bearer ${token}` } });
  const text = await res.text();
  if (!res.ok) {
    console.log(`SEARCH "${q}" FAILED:`, res.status, text.slice(0, 300));
    return null;
  }
  return JSON.parse(text);
}

const main = async () => {
  const tokenJson = await getToken();
  const token = tokenJson.access_token;

  const terms = ['dress', 'blouse', 'jacket', 'top', 'skirt', 'pant', 'shirt'];
  for (const term of terms) {
    const result = await search(token, term);
    if (!result || !result.hits || !result.hits.length) {
      console.log(`"${term}": 0 hits`);
      continue;
    }
    console.log(`"${term}": ${result.hits.length} hits, total=${result.total}`);
    // Look for a real markdown: tieredPrices with >1 distinct price value.
    for (const hit of result.hits) {
      const tiered = hit.tieredPrices || [];
      const distinctPrices = new Set(tiered.map((t) => t.price));
      if (distinctPrices.size > 1 || (hit.productPromotions && hit.productPromotions.length)) {
        console.log('SALE CANDIDATE:', JSON.stringify({
          productId: hit.productId,
          productName: hit.productName,
          hitType: hit.hitType,
          price: hit.price,
          tieredPrices: hit.tieredPrices,
          productPromotions: hit.productPromotions,
          c_isSale: hit.c_isSale,
        }));
      }
    }
  }
};

main().catch((e) => {
  console.error('ERROR', e.message);
  process.exit(1);
});

