const SHORT_CODE = process.env.COMMERCE_API_SHORT_CODE;
const ORG_ID = process.env.COMMERCE_API_ORGANIZATION_ID;
const CLIENT_ID = process.env.COMMERCE_API_CLIENT_ID;
const CLIENT_SECRET = process.env.PWA_KIT_SLAS_CLIENT_SECRET;
const SITE_ID = 'ZimmermannAU';
const BASE = `https://${SHORT_CODE}.api.commercecloud.salesforce.com`;

async function getToken() {
  const basicAuth = Buffer.from(`${CLIENT_ID}:${CLIENT_SECRET}`).toString('base64');
  const res = await fetch(`${BASE}/shopper/auth/v1/organizations/${ORG_ID}/oauth2/token`, {
    method: 'POST',
    headers: { Authorization: `Basic ${basicAuth}`, 'Content-Type': 'application/x-www-form-urlencoded' },
    body: new URLSearchParams({ grant_type: 'client_credentials', channel_id: SITE_ID }).toString(),
  });
  return res.json();
}

async function search(token, q, extra = '') {
  const url = `${BASE}/search/shopper-search/v1/organizations/${ORG_ID}/product-search?siteId=${SITE_ID}&q=${encodeURIComponent(q)}&limit=25&perPricebook=true${extra}`;
  const res = await fetch(url, { headers: { Authorization: `Bearer ${token}` } });
  if (!res.ok) { console.log(`SEARCH "${q}" FAILED`, res.status, (await res.text()).slice(0,200)); return null; }
  return res.json();
}

const main = async () => {
  const { access_token: token } = await getToken();
  const terms = ['dress', 'blouse', 'jacket', 'top', 'skirt', 'pant', 'shirt', 'knit', 'coat', 'swim'];
  let sawTieredKey = false;
  let sawPromoKey = false;
  let sawSaleTrue = false;
  const candidates = [];
  for (const term of terms) {
    const result = await search(token, term);
    if (!result?.hits?.length) { console.log(`"${term}": 0 hits`); continue; }
    for (const hit of result.hits) {
      if ('tieredPrices' in hit) sawTieredKey = true;
      if ('productPromotions' in hit) sawPromoKey = true;
      if (hit.c_isSale === true) { sawSaleTrue = true; candidates.push(hit); }
      if (hit.price != null && hit.pricePerUnit != null && hit.price !== hit.pricePerUnit) candidates.push(hit);
    }
    console.log(`"${term}": ${result.hits.length} hits (total ${result.total})`);
  }
  console.log('EVER SAW tieredPrices key:', sawTieredKey);
  console.log('EVER SAW productPromotions key:', sawPromoKey);
  console.log('EVER SAW c_isSale === true:', sawSaleTrue);
  console.log('CANDIDATES found:', candidates.length);
  for (const c of candidates.slice(0, 5)) console.log(JSON.stringify(c));
};
main().catch((e) => { console.error(e.message); process.exit(1); });
EOF
