  // 1. create basket (v2)
  const createRes = await fetch(`${BASE}/checkout/shopper-baskets/v2/organizations/${ORG_ID}/baskets?siteId=${SITE_ID}`, {
    method: 'POST', headers, body: JSON.stringify({}),
