  const addRes = await fetch(`${BASE}/checkout/shopper-baskets/v2/organizations/${ORG_ID}/baskets/${basketId}/items?siteId=${SITE_ID}`, {
    method: 'POST', headers, body: JSON.stringify([{ productId: VARIANT_ID, quantity: 1 }]),
  });
