  // 3. GET basket by id (v2)
  const getRes = await fetch(`${BASE}/checkout/shopper-baskets/v2/organizations/${ORG_ID}/baskets/${basketId}?siteId=${SITE_ID}`, { headers });
  const getText = await getRes.text();
  if (!getRes.ok) { console.log('GET BASKET (v2 by id) FAILED', getRes.status, getText.slice(0,400)); }
  else {
    const b = JSON.parse(getText);
    const item = b.productItems?.find(i => i.productId === VARIANT_ID);
    j('GET BASKET (v2 by id) line item:', { price: item?.price, basePrice: item?.basePrice, priceAfterItemDiscount: item?.priceAfterItemDiscount, priceAfterOrderDiscount: item?.priceAfterOrderDiscount });
    j('GET BASKET (v2 by id) totals:', { productTotal: b.productTotal, orderTotal: b.orderTotal });
  }

  // 4. GET customer baskets (list) - what useCurrentBasket() actually calls
  const listRes = await fetch(`${BASE}/customer/shopper-customers/v1/organizations/${ORG_ID}/customers/${customerId}/baskets?siteId=${SITE_ID}`, { headers });
  const listText = await listRes.text();
  if (!listRes.ok) { console.log('GET CUSTOMER BASKETS (list) FAILED', listRes.status, listText.slice(0,400)); }
  else {
    const l = JSON.parse(listText);
    const b2 = l.baskets?.find(bb => bb.basketId === basketId);
    const item2 = b2?.productItems?.find(i => i.productId === VARIANT_ID);
    j('GET CUSTOMER BASKETS (list) line item:', { price: item2?.price, basePrice: item2?.basePrice, priceAfterItemDiscount: item2?.priceAfterItemDiscount, priceAfterOrderDiscount: item2?.priceAfterOrderDiscount });
    j('GET CUSTOMER BASKETS (list) totals:', { productTotal: b2?.productTotal, orderTotal: b2?.orderTotal });
  }

  console.log('FINAL basketId (not deleted):', basketId);
};
main().catch((e) => { console.error('ERROR', e.message); process.exit(1); });
EOF
